package org.chromium.chrome.browser.profiles; import org.chromium.content_public.browser.WebContents; public class Profile { private Profile original; public Profile() { original=this; } public Profile(Profile p) { original=p; } public boolean alive=true; public boolean isNativeInitialized(){return alive;} public boolean shutdownStarted(){return !alive;} public boolean isOffTheRecord(){return original!=this;} public Profile getOriginalProfile(){return original;} public static Profile fromWebContents(WebContents w){return w.profile;} }
